private var boundService: LocalService? = null

private val connection = object : ServiceConnection {
    override fun onServiceConnected(name: ComponentName?, binder: IBinder?) {
        boundService = (binder as LocalService.LocalBinder).getService()
    }
    override fun onServiceDisconnected(name: ComponentName?) {
        boundService = null
    }
}

override fun onStart() {
    super.onStart()
    val intent = Intent(this, LocalService::class.java)
    bindService(intent, connection, Context.BIND_AUTO_CREATE)
}

override fun onStop() {
    super.onStop()
    if (isBound) {           // guard: don't unbind twice
        unbindService(connection)
        isBound = false
    }
}

// Process-lifetime holder: Application context, never the Activity
class Repo private constructor(private val ctx: Context) {
    companion object {
        @Volatile private var instance: Repo? = null
        fun get(app: Context): Repo =
            instance ?: synchronized(this) {
                instance ?: Repo(app.applicationContext).also { instance = it }
            }
    }
}

